def corners_of(pts):
    rows=[r for r,c in pts]; cols=[c for r,c in pts]
    mr,Mr,mc,Mc=min(rows),max(rows),min(cols),max(cols)
    return [p for p in pts if p[0] in (mr,Mr) or p[1] in (mc,Mc)]

def hull(pts):
    pts=sorted(set(pts))
    if len(pts)<=2: return pts
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lower=[]
    for p in pts:
        while len(lower)>=2 and cross(lower[-2],lower[-1],p)<=0: lower.pop()
        lower.append(p)
    upper=[]
    for p in reversed(pts):
        while len(upper)>=2 and cross(upper[-2],upper[-1],p)<=0: upper.pop()
        upper.append(p)
    return lower[:-1]+upper[:-1]

def transform(g):
    from collections import Counter
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x!=bg]
    cs=hull(corners_of(pts))
    out=[row[:] for row in g]
    n=len(cs)
    for i in range(n):
        (r1,c1),(r2,c2)=cs[i],cs[(i+1)%n]
        if r1==r2:
            for c in range(min(c1,c2),max(c1,c2)+1):
                if out[r1][c]==bg: out[r1][c]=3
        elif c1==c2:
            for r in range(min(r1,r2),max(r1,r2)+1):
                if out[r][c1]==bg: out[r][c1]=3
    return out

